head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setMultiFocus]<br/>Body Cell 위치정보 객체 배열을 사용하여 불연속적인 Cell 들을 포커스 상태로 설정합니다.",
    "validation" : [
        "배열의 각 요소를 처리할 때 oncellindexchange / onrowindexchange / oncolumnindexchange 이벤트가 조건부로 발생합니다.",
        "범위 Cell { startRow, startCol, endRow, endCol } 요소는 시작 Cell 과 끝 Cell 에서 각각 인덱스 변경 이벤트가 발생할 수 있습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (이벤트 검증 전담)
//  - focusMode 는 'both' 고정. setMultiFocus 처리 시 발생하는 인덱스 이벤트를 검증
//  - selectedCellColor(red) / selectedRowColor(blue) 로 포커스 결과를 배경색으로 구분
//  - 8 Row, 6 Column. col2 는 숨겨진 Column(hidden), col5 는 blockSelect 설정 Column
//  - 인덱스 이벤트(oncellindexchange/onrowindexchange/oncolumnindexchange) 바인딩 후 상세 출력
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="focusMode=both / Column 인덱스 1(col2)=숨김 / Column 인덱스 4(col5)=blockSelect / selectedCellColor=red, selectedRowColor=blue"', '', 'label1');

    // dataList 생성 (6 Column, 8 Row 직접 구성)
    let strData = '';
    strData += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strData += '<w2:columnInfo>';
    strData += '<w2:column id="col1" name="name1" dataType="text"></w2:column>';
    strData += '<w2:column id="col2" name="name2" dataType="text"></w2:column>';
    strData += '<w2:column id="col3" name="name3" dataType="text"></w2:column>';
    strData += '<w2:column id="col4" name="name4" dataType="text"></w2:column>';
    strData += '<w2:column id="col5" name="name5" dataType="text"></w2:column>';
    strData += '<w2:column id="col6" name="name6" dataType="text"></w2:column>';
    strData += '</w2:columnInfo>';
    strData += '<w2:data use="true"></w2:data>';
    strData += '</w2:dataList>';
    $p.data.create(strData);

    let jsonData = [];
    for (let i = 1; i <= 8; i++) {
        jsonData.push({
            "col1" : "c1_" + i, "col2" : "c2_" + i, "col3" : "c3_" + i,
            "col4" : "c4_" + i, "col5" : "c5_" + i, "col6" : "c6_" + i
        });
    }
    dlt_bind.setJSON(jsonData);

    // 조건 설정
    let properties = {
        focusMode         : "both",
        selectedCellColor : "red",
        selectedRowColor  : "blue"
    };
    let cList = $c.gcm.createCList(properties);

    // 인덱스 변경 이벤트 바인딩
    let eList = $c.gcm.createEList(["oncellindexchange", "onrowindexchange", "oncolumnindexchange"]);

    // target 생성 (6 Column : col2 숨김, col5 blockSelect)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' ' + eList + ' dataList="data:dlt_bind" useShiftKey="true" checkAllType="false" id="" style="width:620px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="setMultiFocus 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column1" value="col0"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column2" value="col1(숨김)"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column3" value="col2"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column4" value="col3"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column5" value="col4(block)"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column6" value="col5"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col2" hidden="true" value=""></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col5" blockSelect="true" value=""></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col6" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 인덱스 변경 이벤트 핸들러 : setMultiFocus 처리 중 발생한 이벤트를 시퀀스로 상세 출력
//  (이 샘플은 이벤트 검증 전담이므로 발생 시 각 핸들러가 개별 상세 출력)
scwin.target1_oncellindexchange = function (rowIndex, columnIndex, oldRow, oldColumnIndex) {
    wf_body_bottom.getObj("scwin").setReturnValue("[oncellindexchange] rowIndex=" + rowIndex + ", columnIndex=" + columnIndex + ", oldRow=" + oldRow + ", oldColumnIndex=" + oldColumnIndex);
}

scwin.target1_onrowindexchange = function (rowIndex, oldRow) {
    wf_body_bottom.getObj("scwin").setReturnValue("[onrowindexchange] rowIndex=" + rowIndex + ", oldRow=" + oldRow);
}

scwin.target1_oncolumnindexchange = function (columnIndex, oldColumnIndex) {
    wf_body_bottom.getObj("scwin").setReturnValue("[oncolumnindexchange] columnIndex=" + columnIndex + ", oldColumnIndex=" + oldColumnIndex);
}



// 공통 실행 함수 : cellsPosition 으로 setMultiFocus 호출
//  발생한 인덱스 이벤트 시퀀스를 핸들러가 직접 출력 → 호출 후 getAllFocusedIndex 보조 출력
scwin.runMultiFocus = function (title, cellsPosition) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    bottom.setReturnValue("[" + title + "]");

    // 기존 포커스 제거 후 시작
    target1.removeFocusedCell();

    bottom.setReturnValue("cellsPosition = " + JSON.stringify(cellsPosition));
    bottom.setReturnValue("─ setMultiFocus 처리 중 발생 이벤트 시퀀스 ─");
    target1.setMultiFocus(cellsPosition);

    let rtn = target1.getAllFocusedIndex();
    bottom.setReturnValue("getAllFocusedIndex 결과 = " + JSON.stringify(rtn) + " (포커스 셀 " + rtn.length + "개)");
}



// setMultiFocus 실행 : par_scenario 선택값으로 분기
scwin.btn_run_onclick = function () {
    let scenario = par_scenario.getValue();

    switch (scenario) {
        case "single1" :
            // 단일 Cell 1개 → 해당 Cell 에서 인덱스 이벤트 조건부 발생
            scwin.runMultiFocus("단일 Cell 1개 { row:2, col:3 }", [ { row : 2, col : 3 } ]);
            break;
        case "single2" :
            // 단일 Cell 2개 → 각 요소마다 인덱스 이벤트 조건부 발생
            scwin.runMultiFocus("단일 Cell 2개 { row:0,col:0 },{ row:4,col:5 }", [ { row : 0, col : 0 }, { row : 4, col : 5 } ]);
            break;
        case "range" :
            // 범위 Cell → 시작 Cell 과 끝 Cell 에서 각각 인덱스 이벤트 발생
            scwin.runMultiFocus("범위 Cell { startRow:1, startCol:2, endRow:3, endCol:3 }", [ { startRow : 1, startCol : 2, endRow : 3, endCol : 3 } ]);
            break;
    }
}
